import math
S={'mode':'rev','alpha':0.0,'n':0}
def clamp(x,a,b):
    return max(a,min(b,x))
def control(obs):
    S['n']+=1
    h=obs['hitch_deg']; rig=obs['rig']
    R=rig['trailer_rear']; th=rig['trailer_heading_deg']
    thb=math.radians(th+180.0)
    c0=math.cos(thb); s0=math.sin(thb)
    def tf(x,y):
        rx=x-R[0]; ry=y-R[1]
        return (rx*c0+ry*s0, -rx*s0+ry*c0)
    pts=[]
    views=obs.get('views') or {}
    for name,v in views.items():
        o=v['origin']
        for b,d in v.get('walls',[]):
            x=o[0]+d*math.cos(math.radians(b)); y=o[1]+d*math.sin(math.radians(b))
            fx,fy=tf(x,y)
            if fx>0.3: pts.append((fx,fy))
    st=obs['status']
    if S['mode']=='rev' and (abs(h)>45 or st=='JACKKNIFED'):
        S['mode']='fwd'
    if S['mode']=='fwd':
        if abs(h)<8:
            S['mode']='rev'
        else:
            return (0.0,1.0,-23)
    w=rig.get('trailer_half_width',0.85)+0.15
    tgt=obs.get('target') or {}
    newa=None
    if tgt.get('in_sight') and tgt.get('dist_m') is not None:
        e=rig['eye']; b=math.radians(tgt['bearing_deg']); d=tgt['dist_m']
        fx,fy=tf(e[0]+d*math.cos(b),e[1]+d*math.sin(b))
        if fx>0.5:
            newa=math.degrees(math.atan2(fy,fx))
    if newa is None and len(pts)>=3:
        angs=list(range(-70,71,5)); cs=[]
        for a in angs:
            ua=math.radians(a); ux=math.cos(ua); uy=math.sin(ua)
            c=9.0
            for fx,fy in pts:
                al=fx*ux+fy*uy
                if al>0:
                    lat=abs(fx*uy-fy*ux)
                    if lat<w and al<c: c=al
            cs.append(c-0.004*abs(a))
        best=max(cs); i0=cs.index(best)
        thr=best*0.9
        lo=i0; hi=i0
        while lo>0 and cs[lo-1]>=thr: lo-=1
        while hi<len(cs)-1 and cs[hi+1]>=thr: hi+=1
        newa=(angs[lo]+angs[hi])/2.0
        if S['n']%20==0: print('t',round(obs['t'],1),'best',round(best,1),'a',newa,'h',round(h,1))
    if newa is not None:
        S['alpha']=0.7*S['alpha']+0.3*newa
    e=S['alpha']
    hd=clamp(0.6*e,-35,35)
    steer=-0.75*h-1.5*(hd-h)
    steer=clamp(steer,-34,34)
    return (steer,-0.9,-23)

