import math
S={'mode':'fwd','alpha':None,'fd':0.0,'pts':[],'n':0,'lt':None}
def clamp(x,a,b):
    return max(a,min(b,x))
def ff(h):
    r=math.radians(h)
    return math.degrees(math.atan2(2.75*math.sin(r),2.6-1.05*math.cos(r)))
def vpts(obs):
    out=[]
    for name,v in (obs.get('views') or {}).items():
        o=v['origin']
        for b,d in v.get('walls',[]):
            out.append((o[0]+d*math.cos(math.radians(b)),o[1]+d*math.sin(math.radians(b))))
    return out
def fwd_blocked(obs,pts,steer):
    rig=obs['rig']; F=rig['vehicle_front']; hw=rig['vehicle_half_width']
    d=math.radians(steer)
    for s in (0.3,0.6):
        if abs(d)<1e-3:
            ox,oy,ph=s,0.0,0.0
        else:
            R=2.75/math.tan(d); ph=s/R
            ox=R*math.sin(ph); oy=R*(1-math.cos(ph))
        c=math.cos(ph); sn=math.sin(ph)
        for x,y in pts:
            rx=x-ox; ry=y-oy
            xp=rx*c+ry*sn; yp=-rx*sn+ry*c
            if F-1.6<xp<F+0.15 and abs(yp)<hw+0.1:
                return True
    return False
def control(obs):
    S['n']+=1
    t=obs['t']; dt=obs.get('dt',0.1)
    h=obs['hitch_deg']; rig=obs['rig']; st=obs['status']
    v=obs['motion']['v_mps']
    p=vpts(obs)
    if p: S['pts']=p
    pts=S['pts']
    if S['mode']=='rev' and (abs(h)>21 or st=='JACKKNIFED'):
        S['mode']='fwd'; S['fd']=0.0; S['pts']=[]
        print('t',round(t,1),'-> fwd h',round(h,1))
    if S['mode']=='fwd':
        S['fd']+=abs(v)*dt
        steer=clamp(-1.6*h,-34,34)
        blk=fwd_blocked(obs,pts,steer) if pts else False
        if abs(h)<5 or S['fd']>3.5 or (blk and abs(h)<14):
            S['mode']='rev'; S['pts']=[]
            print('t',round(t,1),'-> rev h',round(h,1),'fd',round(S['fd'],2),'blk',blk)
        elif blk:
            print('t',round(t,1),'fwd blocked h',round(h,1))
            S['mode']='rev'; S['pts']=[]
            wake('forward blocked with hitch %.1f'%h)
        else:
            return (steer,0.8,0)
    R=rig['trailer_rear']; th=rig['trailer_heading_deg']
    thb=math.radians(th+180.0)
    c0=math.cos(thb); s0=math.sin(thb)
    def tf(x,y):
        rx=x-R[0]; ry=y-R[1]
        return (rx*c0+ry*s0,-rx*s0+ry*c0)
    tp=[]
    for x,y in p:
        fx,fy=tf(x,y)
        if fx>0.2: tp.append((fx,fy))
    w=rig.get('trailer_half_width',0.85)+0.25
    newa=None; src=''
    tgt=obs.get('target') or {}
    if tgt.get('in_sight') and tgt.get('dist_m') is not None:
        e=rig['eye']; b=math.radians(tgt['bearing_deg']); d=tgt['dist_m']
        fx,fy=tf(e[0]+d*math.cos(b),e[1]+d*math.sin(b))
        if fx>0.5:
            newa=math.degrees(math.atan2(fy,fx)); src='tgt'
    if newa is None and len(tp)>=3:
        angs=list(range(-80,81,4)); cs=[]
        for a in angs:
            ua=math.radians(a); ux=math.cos(ua); uy=math.sin(ua)
            c=9.0
            for fx,fy in tp:
                al=fx*ux+fy*uy
                if al>0 and abs(fx*uy-fy*ux)<w and al<c: c=al
            cs.append(c-0.005*abs(a))
        best=max(cs); i0=cs.index(best); thr=best*0.9
        lo=i0; hi=i0
        while lo>0 and cs[lo-1]>=thr: lo-=1
        while hi<len(cs)-1 and cs[hi+1]>=thr: hi+=1
        newa=(angs[lo]+angs[hi])/2.0; src='gap%.1f'%best
    if newa is not None:
        S['alpha']=newa if S['alpha'] is None else 0.7*S['alpha']+0.3*newa
    a=S['alpha'] or 0.0
    hd=clamp(-0.5*a,-16,16)
    steer=clamp(ff(h)+2.0*(h-hd),-34,34)
    sp=-0.8 if abs(h)<14 else -0.55
    if S['n']%15==0: print('t',round(t,1),src,'a',round(a,1),'hd',round(hd,1),'h',round(h,1),'st',round(steer,1),'prog',obs['progress']['covered'])
    return (steer,sp,-23)

