import math
L=2.75;A=1.05;L2=2.6
S={'X':0.0,'Y':0.0,'P':0.0,'W':{},'mode':'rev','fd':0.0,'G':None,'D':None,'n':0,'w':0.0,'cmd':(0.0,0.0,-23),'lc':0.0}
CANDS=[-34,-22,-11,0,11,22,34]
def ang(a):
    while a>math.pi: a-=2*math.pi
    while a<-math.pi: a+=2*math.pi
    return a
def clr(X,Y,P,h,walls,geo):
    F,Rr,hw,hx,tf0,tr,tw=geo
    c=math.cos(P); s=math.sin(P)
    Hx=X+hx*c; Hy=Y+hx*s
    T=P-h; ux=-math.cos(T); uy=-math.sin(T)
    m=9.0
    for wx,wy in walls:
        dx=wx-X; dy=wy-Y
        lx=dx*c+dy*s; ly=-dx*s+dy*c
        ox=max(Rr-lx,lx-F,0.0); oy=max(abs(ly)-hw,0.0)
        dc=math.hypot(ox,oy)
        ex=wx-Hx; ey=wy-Hy
        lu=ex*ux+ey*uy; lv=-ex*uy+ey*ux
        ou=max(tf0-lu,lu-tr,0.0); ov=max(abs(lv)-tw,0.0)
        dt_=math.hypot(ou,ov)
        if dc<m: m=dc
        if dt_<m: m=dt_
    return m
def sim(st,dirn,tgt,n,walls,geo,marg):
    X,Y,P,h,sa=st
    clear=9.0
    for i in range(n):
        dmax=36.0*0.1/0.5
        if sa<tgt: sa=min(tgt,sa+dmax)
        else: sa=max(tgt,sa-dmax)
        d=dirn*0.1
        tp=math.tan(math.radians(sa))
        h+=d*tp/L-d*math.sin(h)/L2+d*A*tp*math.cos(h)/(L*L2)
        P+=d*tp/L
        X+=d*math.cos(P); Y+=d*math.sin(P)
        m=clr(X,Y,P,h,walls,geo)
        if m<clear: clear=m
        if clear<marg: return (X,Y,P,h,sa),clear,i
    return (X,Y,P,h,sa),clear,None
def revcost(end,clear,geo,rem,c):
    X,Y,P,h,sa=end
    hx=geo[3]
    Hx=X+hx*math.cos(P); Hy=Y+hx*math.sin(P)
    B=P-h+math.pi
    Tx=Hx+2.6*math.cos(B); Ty=Hy+2.6*math.sin(B)
    e=0.0
    if S['G'] is not None:
        Gx,Gy=S['G']; Dx,Dy=S['D']
        s=(Tx-Gx)*Dx+(Ty-Gy)*Dy
        Qx=Gx+Dx*(s+3.5); Qy=Gy+Dy*(s+3.5)
        e=abs(math.degrees(ang(B-math.atan2(Qy-Ty,Qx-Tx))))
    hd=abs(math.degrees(h))
    cost=e+(0.5 if rem>2.5 else 1.5)*hd+40*max(0.0,0.4-clear)+0.03*abs(c-S['lc'])
    if hd>47: cost+=300
    return cost
def revplan(st,n,walls,geo,marg,rem):
    best=None
    for c in CANDS:
        end,cl,hit=sim(st,-1,c,n,walls,geo,marg)
