    for name,vw in (obs.get('views') or {}).items():
        o=vw['origin']
        for b,d in vw.get('walls',[]):
            x=o[0]+d*math.cos(math.radians(b)); y=o[1]+d*math.sin(math.radians(b))
            wx=X+x*c-y*s; wy=Y+x*s+y*c
            S['W'][(round(wx*5),round(wy*5))]=(wx,wy)
    if len(S['W'])>2500:
        S['W']={k:p for k,p in S['W'].items() if (p[0]-X)**2+(p[1]-Y)**2<200}
    F=rig['vehicle_front']; hw=rig['vehicle_half_width']; hx=rig['hitch'][0]
    tr=math.hypot(rig['trailer_rear'][0]-rig['hitch'][0],rig['trailer_rear'][1]-rig['hitch'][1])
    geo=(F,F-4.6,hw,hx,tr-2.9,tr,rig.get('trailer_half_width',0.85))
