        if S['G'] is None: S['G']=(gx,gy)
        else: S['G']=(0.85*S['G'][0]+0.15*gx,0.85*S['G'][1]+0.15*gy)
    rem=obs['progress']['remaining']
    if S['mode']=='fwd': S['fd']+=abs(v)*dt
    if rem<-1.5:
        if S['w']<t:
            S['w']=t+10; wake('overshoot rem %.1f h %.1f'%(rem,h))
        return (0.0,0.0,-23)
    if S['n']%2==0:
        return S['cmd']
    Hx=X+hx*c; Hy=Y+hx*s
    walls=[p for p in S['W'].values() if (p[0]-Hx)**2+(p[1]-Hy)**2<56]
    hr=math.radians(h)
    st=(X,Y,P,hr,sa)
    c0=clr(X,Y,P,hr,walls,geo)
    marg=max(0.0,min(0.07,c0-0.015))
    sp=-0.5 if rem>2.5 else -0.35
    if S['mode']=='rev':
        best=revplan(st,12,walls,geo,marg,rem)
        if best is not None:
            S['lc']=best[1]
            S['cmd']=(float(best[1]),sp,-23)
            if S['n']%10==1: print('t',round(t,1),'rev c',best[1],'hend',round(best[2],1),'clr',round(best[3],2),'c0',round(c0,2),'h',round(h,1),'rem',rem)
            return S['cmd']
        S['mode']='fwd'; S['fd']=0.0
        print('t',round(t,1),'-> fwd c0',round(c0,2),'h',round(h,1))
    if S['fd']>=0.6 or S['fd']>3.0:
        rb=revplan(st,18,walls,geo,min(marg,0.07),rem)
        if (rb is not None and abs(rb[2])<45 and rb[3]>0.15) or S['fd']>3.0:
            S['mode']='rev'
            print('t',round(t,1),'-> rev fd',round(S['fd'],2),'h',round(h,1),rb)
            if rb is not None:
                S['lc']=rb[1]; S['cmd']=(float(rb[1]),sp,-23)
            else:
                S['cmd']=(0.0,0.0,-23)
                if S['w']<t:
                    S['w']=t+10; wake('stuck: no safe move h %.1f'%h)
            return S['cmd']
    bf=None
    for cc in CANDS:
        end,cl,hit=sim(st,1,cc,8,walls,geo,marg)
        if hit is None:
            k=0.6*abs(math.degrees(end[3]))+60*max(0.0,0.5-cl)
            if bf is None or k<bf[0]: bf=(k,cc,cl)
    if bf is None:
        S['mode']='rev'
        if S['w']<t:
            S['w']=t+10; wake('no safe forward move h %.1f c0 %.2f'%(h,c0))
        S['cmd']=(0.0,0.0,-23)
        return S['cmd']
    S['cmd']=(float(bf[1]),0.6,-23)
    if S['n']%10==1: print('t',round(t,1),'fwd c',bf[1],'clr',round(bf[2],2),'h',round(h,1),'fd',round(S['fd'],2))
    return S['cmd']

