import math
phase='rev'
ef=0.0
t_print=-10.0
last_src='none'

def clamp(x,a,b):
    return max(a,min(b,x))

def control(obs):
    global phase,ef,t_print,last_src
    h=obs['hitch_deg']
    if phase=='rev' and abs(h)>48:
        phase='fwd'
    if phase=='fwd':
        if abs(h)<8:
            phase='rev'
        else:
            return (clamp(-1.0*h,-45,45),1.2,170)
    psi=math.radians(180.0-h)
    cp=math.cos(psi); sp=math.sin(psi)
    rig=obs['rig']
    tr=rig['trailer_rear']
    def to_tw(x,y):
        dx=x-tr[0]; dy=y-tr[1]
        return (dx*cp+dy*sp, dx*sp-dy*cp)
    P=[]
    views=obs.get('views') or {}
    for k,vw in views.items():
        if not vw: continue
        o=vw.get('origin',[0,0])
        for pt in vw.get('walls',[]) or []:
            b=math.radians(pt[0]); d=pt[1]
            P.append(to_tw(o[0]+d*math.cos(b),o[1]+d*math.sin(b)))
    def center(lo,hi):
        L=[w for u,w in P if lo<=u<=hi and w>0.9]
        R=[w for u,w in P if lo<=u<=hi and w<-0.9]
        wl=min(L) if L else None
        wr=max(R) if R else None
        if wl is not None and wr is not None:
            return (wl+wr)/2.0
        if wl is not None:
            return min(0.0,wl-2.5)
        if wr is not None:
            return max(0.0,wr+2.5)
        return None
    aim=None; src='none'
    if P:
        far=center(3,11); near=center(-2,4)
        if far is not None and near is not None:
            aim=(6.0,0.6*far+0.4*near); src='both'
        elif far is not None:
            aim=(7.0,far); src='far'
        elif near is not None:
            aim=(4.0,near); src='near'
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None and tg['dist_m']<18:
        eye=rig['eye']; b=math.radians(tg['bearing_deg'])
        u,w=to_tw(eye[0]+tg['dist_m']*math.cos(b),eye[1]+tg['dist_m']*math.sin(b))
        if u>1.5:
            aim=(max(u,3.0),w); src='target'
    if aim is not None:
        e=math.degrees(math.atan2(aim[1],aim[0]))
        ef=0.7*ef+0.3*e
        last_src=src
    hd=clamp(1.3*ef,-35,35)
    steer=clamp(3.0*(h-hd),-45,45)
    err=abs(h-hd)
    spd=-1.0 if err<12 else -0.6
    if obs['t']-t_print>3:
        t_print=obs['t']
        print('t=%.1f h=%.1f hd=%.1f ef=%.1f src=%s np=%d'%(obs['t'],h,hd,ef,last_src,len(P)))
    return (steer,spd,170)

