import math
X=-1.3;Y=0.05;YAW=math.radians(-40.0);phase='rev';n=0;fx0=None;pphi=None;pd=0.0;RAIL=None;woke=False
L=1.25
XC=-1.6
def cl(v,a):
    return max(-a,min(a,v))
def wrap(a):
    return (a+180.0)%360.0-180.0
def corner_y(obs):
    rig=obs['rig']
    fx=rig.get('vehicle_front',1.5)
    if isinstance(fx,(list,tuple)): fx=fx[0]
    hw=rig.get('vehicle_half_width',0.525)
    return Y+fx*math.sin(YAW)-hw*math.cos(YAW)
def control(obs):
    global X,Y,YAW,phase,n,fx0,pphi,pd,RAIL,woke
    n+=1
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];st=math.radians(obs['steer_deg'])
    YAW+=v*math.tan(st)/L*dt
    X+=v*math.cos(YAW)*dt;Y+=v*math.sin(YAW)*dt
    cy=corner_y(obs)
    if RAIL is None: RAIL=cy
    phi=obs['hitch_deg']
    if pphi is None: pphi=phi
    pd=0.6*pd+0.4*(phi-pphi)/dt
    pphi=phi
    rig=obs['rig'];hx,hy=rig['hitch'];rx,ry=rig['trailer_rear']
    f=0.85/1.3
    ax=hx+(rx-hx)*f;ay=hy+(ry-hy)*f
    c=math.cos(YAW);s=math.sin(YAW)
    wx=X+ax*c-ay*s;wy=Y+ax*s+ay*c
    th=math.degrees(YAW)-phi
    rem=obs['progress']['remaining']
    gap=cy-RAIL
    if n%10==0:
        print(round(obs['t'],1),phase,'phi',round(phi,1),'yaw',round(math.degrees(YAW),1),'ax',round(wx,2),round(wy,2),'th',round(th,1),'gap',round(gap,2),'rem',round(rem,2))
    if phase=='rev' and abs(phi)>55:
        phase='fwd';fx0=None
    if phase=='fwd':
        if fx0 is None: fx0=(X,Y)
        dd=math.hypot(X-fx0[0],Y-fx0[1])
        if abs(phi)<15 or dd>1.5:
            phase='rev'
        else:
            if gap<0.2:
                if not woke:
                    woke=True;wake('fwd needed but front near right rail')
                return (0.0,0.0,150)
            sg=-1.0 if phi>0 else 1.0
            return (sg*25.0,0.4,150)
    e=wx-XC
    beta=90.0+math.degrees(math.atan(1.2*e))
    beta=max(90.0,min(180.0,beta))
    thd=beta-180.0
    phid=cl(1.0*wrap(th-thd),30)
    steer=cl(2.0*(phi-phid)+0.7*pd,45)
    if gap<0.15: steer=min(steer,-5.0)
    elif gap<0.3: steer=min(steer,10.0)
    elif gap<0.45: steer=min(steer,25.0)
    sp=-0.3 if rem>1.5 else -0.25
