import math
mode='rev'
fwd_d=0.0
last_phi=0.0
tick=0
HW=1.275
def cl(x,a,b):
    return max(a,min(b,x))
def control(obs):
    global mode,fwd_d,last_phi,tick
    tick+=1
    dt=obs.get('dt',0.1) or 0.1
    rig=obs['rig']; h=obs['hitch_deg']; th=rig['trailer_heading_deg']
    R=rig['trailer_rear']
    v=obs['motion']['v_mps']
    tb=math.radians(th+180); tn=math.radians(th+90)
    def loc(x,y):
        dx=x-R[0]; dy=y-R[1]
        return (dx*math.cos(tb)+dy*math.sin(tb), dx*math.cos(tn)+dy*math.sin(tn))
    pts=[]
    for name,vw in (obs.get('views') or {}).items():
        if not vw: continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]) or []:
            pts.append(loc(ox+d*math.cos(math.radians(b)), oy+d*math.sin(math.radians(b))))
    phi=last_phi
    fmax=None
    if pts:
        cands=[]
        for pd in range(-64,65,4):
            a=math.radians(pd); cu=math.cos(a); sw=math.sin(a)
            free=14.0
            for (u,w) in pts:
                p=u*cu+w*sw
                if p<=0 or p>=free: continue
                q=-u*sw+w*cu
                if abs(q)<HW+0.6:
                    free=p
            cands.append((pd,free))
        fmax=max(f for _,f in cands)
        groups=[];cur=[]
        for pd,f in cands:
            if f>=fmax-1.0: cur.append(pd)
            else:
                if cur: groups.append(cur)
                cur=[]
        if cur: groups.append(cur)
        lp=math.degrees(last_phi)
        g=min(groups,key=lambda g: min(abs(x-lp) for x in g))
        phi=math.radians(sum(g)/len(g))
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None:
        e=rig['eye']; d=tg['dist_m']; b=math.radians(tg['bearing_deg'])
        u,w=loc(e[0]+d*math.cos(b), e[1]+d*math.sin(b))
