mode='fwd'
fwd_d=0.0
fwd_steer=30.0
fwd_len=2.0
last_phi=0.0
tick=0
HW=1.275
def cl(x,a,b):
    return max(a,min(b,x))
def front_clear(obs):
    rig=obs['rig']
    fr=rig.get('vehicle_front',5.3)
    if isinstance(fr,(list,tuple)): fr=fr[0]
    vhw=rig.get('vehicle_half_width',1.275) or 1.275
    cr=99.0; clf=99.0
    for name in ('direct','periphery'):
        vw=(obs.get('views') or {}).get(name)
        if not vw: continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]) or []:
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            if x<1.0 or x>fr+1.0: continue
            if y<0: cr=min(cr,-y-vhw)
            else: clf=min(clf,y-vhw)
    return cr,clf
def control(obs):
    global mode,fwd_d,last_phi,tick,fwd_steer,fwd_len
    tick+=1
    dt=obs.get('dt',0.1) or 0.1
    rig=obs['rig']; h=obs['hitch_deg']; th=rig['trailer_heading_deg']
    R=rig['trailer_rear']
    v=obs['motion']['v_mps']
    cr,clf=front_clear(obs)
    if tick%20==0:
        print('t=%.0f m=%s h=%.1f cr=%.2f cl=%.2f v=%.2f st=%.1f'%(obs['t'],mode,h,cr,clf,v,obs['steer_deg']))
    if mode=='fwd':
        if v>0: fwd_d+=v*dt
        stop=fwd_d>fwd_len or (clf<0.35 and fwd_steer>0) or (cr<0.35 and fwd_steer<0 and fwd_d>0.5) or (fwd_steer==0 and abs(h)<12 and fwd_d>2)
        if stop:
            mode='rev'
        else:
            return (fwd_steer,0.9,-41)
    tb=math.radians(th+180); tn=math.radians(th+90)
    def loc(x,y):
        dx=x-R[0]; dy=y-R[1]
        return (dx*math.cos(tb)+dy*math.sin(tb), dx*math.cos(tn)+dy*math.sin(tn))
    pts=[]
    for name,vw in (obs.get('views') or {}).items():
        if not vw: continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]) or []:
            pts.append(loc(ox+d*math.cos(math.radians(b)), oy+d*math.sin(math.radians(b))))
    phi=last_phi
    fmax=None
    if pts:
        cands=[]
        for pd in range(-64,65,4):
            a=math.radians(pd); cu=math.cos(a); sw=math.sin(a)
            free=14.0
            for (u,w) in pts:
                p=u*cu+w*sw
                if p<=0 or p>=free: continue
                q=-u*sw+w*cu
                if abs(q)<HW+0.6:
                    free=p
            cands.append((pd,free))
        fmax=max(f for _,f in cands)
        groups=[];cur=[]
        for pd,f in cands:
            if f>=fmax-1.0: cur.append(pd)
            else:
                if cur: groups.append(cur)
                cur=[]
        if cur: groups.append(cur)
        lp=math.degrees(last_phi)
        g=min(groups,key=lambda g: min(abs(x-lp) for x in g))
        phi=math.radians(sum(g)/len(g))
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None:
        e=rig['eye']; d=tg['dist_m']; b=math.radians(tg['bearing_deg'])
        u,w=loc(e[0]+d*math.cos(b), e[1]+d*math.sin(b))
        if u>0 and math.hypot(u,w)<18:
            phi=math.atan2(w,u)
    phi=0.6*phi+0.4*last_phi
    last_phi=phi
    hdes=cl(math.degrees(math.atan(2*10.2*math.sin(phi)/8.0)),-30,30)
    if abs(h)>50:
        mode='fwd'; fwd_d=0.0; fwd_steer=0.0; fwd_len=8.0
        return (0.0,0.9,-41)
    steer=cl(hdes/2.6+1.2*(h-hdes),-42,42)
    sp=-0.8
    if cr<1.0:
        if cr<0.15: cap=-8.0
        else: cap=-8.0+22.0*(cr-0.15)/0.85
        if steer>cap:
            steer=cap; sp=-0.6
        if h>38 and cr<0.3:
            mode='fwd'; fwd_d=0.0; fwd_steer=30.0; fwd_len=2.5
            return (30.0,0.0,-41)
    if clf<1.0:
        if clf<0.15: capl=8.0
        else: capl=8.0-22.0*(clf-0.15)/0.85
        if steer<capl:
            steer=capl; sp=-0.6
        if h<-38 and clf<0.3:
            mode='fwd'; fwd_d=0.0; fwd_steer=-30.0; fwd_len=2.5
            return (-30.0,0.0,-41)
    if h>40: steer=max(steer,20.0)
    if h<-40: steer=min(steer,-20.0)
    if abs(h-hdes)>15: sp=max(sp,-0.6)
    if fmax is not None and fmax<4: sp=max(sp,-0.6)
    return (steer, sp, -41)

