import math
L=3.9;A=0.35;LT=10.2;HW=1.275;TF=1.4;TR=12.1
X=0.0;Y=0.0;PSI=0.0;last_t=None;odo=0.0
cells={}
mode='rev';fsteer=0.0;fdist=0.0;flen=2.5;nf=0;woke=False
tick=0;last_phi=0.0
GZ=[(-72,15),(-41,10),(53,10)];gi=0;gc=0
VFR=5.3;VRR=-0.9
R10=math.radians(10)
def cl(x,a,b):
    return max(a,min(b,x))
def ingest(obs):
    c=math.cos(PSI);s=math.sin(PSI)
    for name,vw in (obs.get('views') or {}).items():
        if not vw: continue
        ox,oy=vw['origin']
        prev=None
        for b,d in (vw.get('walls') or []):
            x=ox+d*math.cos(math.radians(b));y=oy+d*math.sin(math.radians(b))
            seq=[(x,y)]
            if prev is not None:
                gx=x-prev[0];gy=y-prev[1];g=math.hypot(gx,gy)
                if 0.3<g<2.5:
                    n=int(g/0.3)
                    seq=[(prev[0]+gx*k/(n+1),prev[1]+gy*k/(n+1)) for k in range(1,n+1)]+seq
            prev=(x,y)
            for px,py in seq:
                wx=X+px*c-py*s;wy=Y+px*s+py*c
                cells[(int(round(wx/0.35)),int(round(wy/0.35)))]=(wx,wy,odo)
def localpts(cx,cy,rad):
    c=math.cos(PSI);s=math.sin(PSI);out=[]
    for k,(wx,wy,o) in list(cells.items()):
        if odo-o>20:
            del cells[k];continue
        dx=wx-X;dy=wy-Y
        x=dx*c+dy*s;y=-dx*s+dy*c
        if (x-cx)**2+(y-cy)**2<rad*rad: out.append((x,y))
    return out
def rectd(px,py,x,y,c,s,umin,umax):
    dx=px-x;dy=py-y;u=dx*c+dy*s;w=-dx*s+dy*c
    if u<umin: du=umin-u
    elif u>umax: du=u-umax
