ang=math.atan2(4.5,-4.0)
for k in range(1,7):
    RAW.append((-34+3*k*math.cos(ang),14.5+3*k*math.sin(ang)))
P=[];S=[];SK=0.0
acc=0.0
for i in range(len(RAW)-1):
    a=RAW[i];b=RAW[i+1];d=math.hypot(b[0]-a[0],b[1]-a[1]);n=max(1,int(d/0.5))
    for k in range(n):
        P.append((a[0]+(b[0]-a[0])*k/n,a[1]+(b[1]-a[1])*k/n));S.append(acc+d*k/n)
    acc+=d
    if i==6: SK=acc
P.append(RAW[-1]);S.append(acc)
idx=0;tick=0;woke_end=False;mode='run';hw=False
GZ=[(-41,10),(-72,10),(53,10)];gi=0;gc=0
SEED='-20.2,-2.2 -18.2,-1.7 -17.2,-2.6 -16.7,-1.7 -16.2,-1.7 -14.7,-2.6 -14.1,-3.0 -13.2,-2.3 -12.7,-2.6 -12.2,-2.8 -11.6,-3.4 -11.1,-3.2 -10.6,-3.4 -10.1,-3.3 -9.6,-2.9 -9.0,-3.8 -8.6,-3.5 -8.0,-3.8 -7.0,-3.5 -6.5,-3.8 -5.7,-3.8 -5.0,-3.5 -3.9,-3.7 -3.1,-3.7 -2.1,-3.7 -1.1,-3.6 -0.3,-3.4 0.6,-3.3 1.2,-3.2 2.1,-3.0 -28.7,3.0 -28.0,4.7 -27.9,12.5 -25.7,0.6 -25.2,1.8 -25.1,11.4 -23.6,12.6 -22.9,10.0 -18.9,7.8 -17.9,7.4 -17.4,7.3 -14.5,6.5 -12.7,5.9 -11.2,5.6 -9.7,5.5 -7.7,5.2 -6.2,4.9 -4.6,4.9 -3.5,4.8 -2.0,5.2 -1.5,5.5 -26.8,3.2 -25.8,3.1 -25.3,3.0 -25.1,1.6 -24.8,2.8 -24.1,1.5 -23.5,1.8 -21.5,-0.1 -21.0,-0.0 -20.3,9.3 -20.0,-0.8 -20.0,9.5 -19.9,8.9 -19.7,-0.6 -19.2,-0.8 -18.6,8.4 -18.2,-1.5 -17.8,7.7 -17.7,-1.4 -17.2,6.9 -16.3,6.6 -16.3,-1.9 -15.5,-2.2 -14.7,-2.4 -13.8,-2.6 -13.0,-2.9'
for tok in SEED.split():
    a,b=tok.split(',');x=float(a);y=float(b)
    cells[(int(round(x/0.35)),int(round(y/0.35)))]=(x,y,0.0)
def cl(x,a,b):
    return max(a,min(b,x))
def wrap(a):
    return math.atan2(math.sin(a),math.cos(a))
def ingest(obs):
    c=math.cos(PSI);s=math.sin(PSI)
    for name,vw in (obs.get('views') or {}).items():
        if not vw: continue
        ox,oy=vw['origin']
        for b,d in (vw.get('walls') or []):
            x=ox+d*math.cos(math.radians(b));y=oy+d*math.sin(math.radians(b))
            wx=X+x*c-y*s;wy=Y+x*s+y*c
