def rectd(px,py,x,y,c,s,umin,umax,hw):
    dx=px-x;dy=py-y;u=dx*c+dy*s;w=-dx*s+dy*c
    du=umin-u if u<umin else (u-umax if u>umax else 0.0)
    dw=max(0.0,abs(w)-hw)
    return math.hypot(du,dw)
def mind(pose,pts):
    x,y,psi,h=pose
