        if d2<m: m=d2
    return m
def sim(pose0,st0,target,sign,dist,n,checks):
    x,y,psi,h=pose0;st=st0;ds=dist/n;dmax=math.radians(20)*ds/0.6
    poses=[]
    for i in range(1,n+1):
        st+=cl(target-st,-dmax,dmax)
        v=sign*ds
        dpsi=v*math.tan(st)/L
        dth=(v*math.sin(h)+dpsi*A*math.cos(h))/LT
        x+=v*math.cos(psi);y+=v*math.sin(psi);psi+=dpsi;h+=dpsi-dth
        if i in checks: poses.append((x,y,psi,h))
    return poses
def halt(sd,g,msg):
    global mode,hw
    mode='halt'
    if not hw:
        hw=True;print(msg)
        try: wake(msg)
        except Exception: pass
    return (sd,0.0,g)
def _ctl(obs):
    global X,Y,PSI,last_t,odo,idx,tick,woke_end,gi,gc
    tick+=1
    t=obs['t'];v=obs['motion']['v_mps'];sd=obs['steer_deg'];st=math.radians(sd)
    if last_t is not None:
        dtt=cl(t-last_t,0.0,0.3)
        X+=v*math.cos(PSI)*dtt;Y+=v*math.sin(PSI)*dtt;PSI+=v*math.tan(st)/L*dtt;odo+=abs(v)*dtt
    last_t=t
    ingest(obs)
    gc+=1
    if gc>=GZ[gi][1]:
        gc=0;gi=(gi+1)%len(GZ)
    g=GZ[gi][0]
    if mode=='halt': return (sd,0.0,g)
    rig=obs['rig'];h=math.radians(obs['hitch_deg']);th=math.radians(rig['trailer_heading_deg'])
    Hh=rig['hitch']
    axv=(Hh[0]-LT*math.cos(th),Hh[1]-LT*math.sin(th))
    c=math.cos(PSI);s=math.sin(PSI)
    ax=X+axv[0]*c-axv[1]*s;ay=Y+axv[0]*s+axv[1]*c
    beta=PSI+th+math.pi
    bi=idx;bd=1e9
    for i in range(idx,min(idx+40,len(P))):
        d=(P[i][0]-ax)**2+(P[i][1]-ay)**2
        if d<bd: bd=d;bi=i
    idx=bi
    j=min(len(P)-1,idx+12)
    tx,ty=P[j]
    Ld=max(2.0,math.hypot(tx-ax,ty-ay))
    alpha=wrap(math.atan2(ty-ay,tx-ax)-beta)
    kap=2*math.sin(alpha)/Ld
    hdes=math.asin(cl(-kap*LT,-0.77,0.77))
    steer=math.atan(L*(math.sin(h)/LT+0.5*(h-hdes))/(1-A*math.cos(h)/LT))
    sdeg=cl(math.degrees(steer),-42,42)
    if abs(h)>math.radians(55): return halt(sd,g,'hitch over 55, halted')
    pts=localpts()
    cur=(0.0,0.0,0.0,h)
    near=[p for p in pts if mind(cur,[p])<4.0][:300]
    poses=sim(cur,st,math.radians(sdeg),-1,2.0,8,(2,4,6,8))
    dm=min(mind(p,near) for p in poses) if near else 9.0
    if dm<0.1: return halt(sd,g,'predicted contact dm=%.2f, halted'%dm)
    sp=-0.8
    if abs(h-hdes)>math.radians(15): sp=-0.5
    if dm<0.4: sp=-0.35
    if S[idx]>SK-4 and not woke_end:
        woke_end=True
        try: wake('near end of mapped path')
        except Exception: pass
    if woke_end: sp=max(sp,-0.4)
    if tick%20==0: print('t=%.0f s=%.1f ax=%.1f,%.1f h=%.1f hd=%.1f st=%.1f dm=%.2f rem=%s'%(t,S[idx],ax,ay,math.degrees(h),math.degrees(hdes),sdeg,dm,(obs.get('progress') or {}).get('remaining')))
    return (sdeg,sp,g)
def control(obs):
    try:
        return _ctl(obs)
    except Exception as ex:
        print('ERR',repr(ex))
        try: wake('controller exception '+repr(ex))
        except Exception: pass
        return (0.0,0.0,-41)

